NAME = 'SrKDIjekav: Serbian Bible Daničić-Karadžić Ijekavski'
BOOK = 'Joel'

CHAPTERS = {
    1: {
        1: 'Ријеч Господња која дође Јоилу сину Фатуилову.',
        2: 'Чујте, старци; слушајте, сви становници земаљски; је ли овако што било за вашега времена или за времена ваших отаца?',
        3: 'Приповиједајте то синовима својим, и синови ваши својим синовима, и њихови синови потоњему кољену.',
        4: 'Што оста иза гусјенице изједе скакавац, и што оста иза скакавца изједе хрушт, и што оста иза хрушта изједе црв.',
        5: 'Отријезните се, пијанице, и плачите; и ридајте сви који пијете вино, за новијем вином, јер се оте из уста ваших.',
        6: 'Јер дође на земљу моју силан народ и небројен; зуби су му као у лава и кутњаци као у лавице.',
        7: 'Потр винову лозу моју, и смокве моје покида, сасвијем их огули и побаца, те им се гране бијеле.',
        8: 'Ридај као младица опасана костријећу за мужем младости своје.',
        9: 'Неста дара и наљева из дома Господњега; туже свештеници, слуге Господње.',
        10: 'Опустје поље, тужи земље; јер је потрвено жито, усахло вино, нестало уља.',
        11: 'Стидите се ратари, ридајте виноградари, пшенице ради и јечма ради, јер пропаде жетва на њиви;',
        12: 'Лоза посахну и смоква увену; шипак и палма и јабука и сва дрвета пољска посахнуше, јер неста радости између синова људских.',
        13: 'Опашите се и плачите свештеници; ридајте који служите олтару, дођите, ноћујте у костријети, слуге Бога мојега; јер се уноси у дом Бога вашега дар и наљев.',
        14: 'Наредите пост, огласите празник, скупите старјешине, све становнике земаљске, у дом Господа Бога својега, и вапијте ка Господу:',
        15: 'Јаох дана! јер је близу дан Господњи, и доћи ће као погибао од свемогућега.',
        16: 'Није ли нестало хране испред очију наших, радости и весеља из дома Бога нашега?',
        17: 'Сјеме иструхну под грудама својим, пусте су житнице, разваљене спреме, јер посахну жито.',
        18: 'Како уздише стока! како су се смела говеда! јер немају паше; и овце гину.',
        19: 'К теби, Господе, вичем, јер огањ сажеже паше у пустињи, и пламен попали сва дрвета у пољу.',
        20: 'И звијерје пољско погледа за тобом, јер усахнуше потоци водени и огањ сажеже паше у пустињи.',
    },
    2: {
        1: 'Трубите у трубу на Сиону, и вичите на светој гори мојој, нека дркћу сви становници земаљски, јер иде дан Господњи, јер је близу,',
        2: 'Дан, када је мрак и тама, дан, када је облак и магла; како се зора разастире поврх гора, тако иде народ велик и силан, какога није било откад је вијека нити ће га послије кад бити од кољена до кољена.',
        3: 'Пред њим прождире огањ, а за њим пали пламен; земља је пред њим као врт Едемски, а за њим пустиња пуста, ништа неће утећи од њега.',
        4: 'На очима су као коњи и трчаће као коњици.',
        5: 'Скакаће поврх гора топоћући као кола, праскајући као пламен огњени који сажиже стрњику, као силан народ спреман за бој.',
        6: 'Пред њим ће се препадати народи, свако ће лице поцрњети.',
        7: 'Они ће трчати као јунаци, као војници скакаће на зид, и сваки ће ићи својим путем, нити ће отступати са своје стазе.',
        8: 'И један другога неће тискати, сваки ће ићи својим путем, и на мачеве навирући неће се ранити.',
        9: 'По граду ће ходити, по зидовима ће трчати, у куће ће се пети, улазиће кроз прозоре као лупеж.',
        10: 'Пред њима ће се земља трести, небеса ће се поколебати, сунце ће и мјесец помркнути и звијезде ће устегнути свјетлост своју.',
        11: 'А Господ ће пустити глас свој пред војском својом, јер ће око његов бити врло велик, јер ће бити силан онај који ће извршити вољу његову; јер ће дан Господњи бити велик и врло страшан, и ко ће га поднијети?',
        12: 'Зато још говори Господ: обратите се к мени свијем срцем својим и постећи и плачући и тужећи.',
        13: 'И раздерите срца своја а не хаљине своје, и обратите се ка Господу Богу својему, јер је милостив и жалостив, спор на гњев и обилан милосрђем и каје се ода зла.',
        14: 'Ко зна, неће ли се повратити и раскајати се, и оставити иза тога благослов, дар и наљев за Господа Бога вашега.',
        15: 'Трубите у трубу на Сиону, наредите пост, прогласите светковину.',
        16: 'Саберите народ, освештајте сабор, скупите старце, саберите дјецу и која сисају; женик нека изиде из своје клијети и невјеста из ложнице своје.',
        17: 'Између тријема и олтара нека плачу свештеници, слуге Господње, и нека реку: прости, Господе, народу својему, и не дај нашљедства својега под срамоту, да њим обладају народи; зашто да реку у народима: гдје им је Бог?',
        18: 'И Господ ће ревновати за земљу своју и пожалиће народ свој.',
        19: 'И Господ ће одговорити и рећи ће своме народу: ево, ја ћу вам послати жита и вина и уља, и бићете га сити, и нећу вас више дати под срамоту међу народима.',
        20: 'Јер ћу удаљити од вас сјеверца, и одагнати га у земљу суху и пусту, предњу чету његову у источно море а задњу у море западно, и подигнуће се смрад његов, и трулеж ће се његов подигнути, пошто учини велике ствари.',
        21: 'Не бој се, земљо, радуј се и весели се, јер ће Господ учинити велике ствари.',
        22: 'Не бојте се, звијери пољске; јер ће се зелењети пасишта у пустињи и дрвета ће носити род свој, смоква ће и лоза винова давати силу своју.',
        23: 'И ви, синови Сионски, радујте се и веселите се у Господу Богу својем, јер ће вам дати дажд на вријеме, и спустиће вам дажд рани и позни на вријеме.',
        24: 'И гумна ће се напунити жита, а каце ће се прељевати вином и уљем.',
        25: 'И накнадићу вам године које изједе скакавац, хрушт и црв и гусјеница, велика војска моја, коју слах на вас.',
        26: 'И јешћете изобила, и бићете сити и хвалићете име Господа Бога својега, који учини с вама чудеса, и народ мој неће се посрамити довијека.',
        27: 'И познаћете да сам ја усред Израиља, и да сам ја Господ Бог ваш, и да нема другога, и народ мој неће се посрамити довијека.',
        28: 'И послије ћу излити дух свој на свако тијело, и прорицаће синови ваши и кћери ваше, старци ће ваши сањати сне, младићи ће ваши виђати утваре.',
        29: 'И на слуге ћу и на слушкиње у оне дане излити дух свој;',
        30: 'И учинићу чудеса на небу и на земљи, крв и огањ и пушење дима.',
        31: 'Сунце ће се претворити у таму и мјесец у крв прије него дође велики и страшни дан Господњи.',
        32: 'И сваки који призове име Господње спашће се; јер ће на гори Сиону и у Јерусалиму бити спасење, као што је рекао Господ, и у остатку који позове Господ.',
    },
    3: {
        1: 'Јер, гле, у оне дане и у оно вријеме, кад вратим робље Јудино и Јерусалимско,',
        2: 'Сабраћу све народе, и свешћу их у долину Јосафатову, и ондје ћу се судити с њима за свој народ и за нашљедство своје Израиља, којега расијаше међу народе и раздијелише земљу моју;',
        3: 'И за мој народ бацаше ждријеб, и даваше дијете за курву, и продаваше дјевојку за вино, те пише.',
        4: 'И шта хоћете ви са мном, Тире и Сидоне, и сви крајеви Палестински? хоћете ли да ми платите? и хоћете ли да ми вратите? Одмах ћу вам без оклијевања платити плату вашу на вашу главу.',
        5: 'Јер узесте сребро моје и злато моје, и најљепше закладе моје унесосте у своје цркве.',
        6: 'И синове Јудине и синове Јерусалимске продадосте синовима Грчким да бисте их отјерали далеко од међе њихове.',
        7: 'Ево, ја ћу их дигнути с мјеста куда их продадосте, и платићу вам плату вашу на вашу главу.',
        8: 'И продаћу ваше синове и ваше кћери у руке синовима Јудинијем, и они ће их продати Савејцима у народ даљни, јер Господ рече.',
        9: 'Објавите ово по народима, огласите рат, подигните јунаке нека дођу и иду сви војници.',
        10: 'Раскујте раонике своје на мачеве, и српове своје на копља; ко је слаб, нека рече: јунак сам.',
        11: 'Скупите се и ходите, сви народи унаоколо, и саберите се! тамо сведи, Господе, јунаке своје.',
        12: 'Нека се подигну и дођу народи у долину Јосафатову; јер ћу ондје сјести да судим свијем народима унаоколо.',
        13: 'Замахните српом, јер је жетва узрела; ходите, сиђите, јер је тијесак пун, каце се прељевају; јер је злоћа њихова велика.',
        14: 'Гомиле, гомиле у долини судској; јер је дан Господњи близу у долини судској.',
        15: 'Сунце ће и мјесец помркнути, и звијезде ће устегнути своју свјетлост.',
        16: 'И Господ ће рикнути са Сиона, и из Јерусалима ће пустити глас свој, и затрешће се небо и земља; али ће Господ бити уточиште своме народу и крјепост синовима Израиљевијем.',
        17: 'И познаћете да сам ја Господ Бог ваш, који наставам у Сиону, у светој гори својој; и Јерусалим ће бити свет, и туђинци неће више ићи по њему.',
        18: 'И тада ће горе капати слатким вином, и хумови ће се топити од млијека, и свијем потоцима Јудинијем тећи ће вода, и изаћи ће извор из дома Господњега и натопиће долину Ситим.',
        19: 'Мисир ће опустјети, и Едомска ће бити пуста пустиња за насиље учињено синовима Јудинијем, јер пролише крв праву у земљи њиховој.',
        20: 'А Јуда ће стајати довијека и Јерусалим од кољена до кољена.',
        21: 'И очистићу крв њихову, које не очистих; и Господ ће наставати у Сиону.',
    },
}
